/* Max 9 v8.codebox: add paraminfo comments to existing rnbo~ objects.
 * 1. Set SOURCE_DIRECTORY below to your RNBO folder (absolute Max/POSIX path),
 *    the same directory that holds the *_paraminfo.txt files.
 * 2. Paste this entire script into a v8.codebox in the SAME patch that contains
 *    the rnbo~ objects (e.g. generated by generate_test_patchers.js, or built
 *    manually as `rnbo~ @autobuild 0 @annotation_name effect_name`).
 * 3. Send bang (or addcomments). Progress/errors appear in the Max console/outlet.
 *
 * For every rnbo~ in THIS patch it opens the rnbo~ subpatcher, creates ONE
 * comment object whose top-left corner sits directly below the `out~ 1`
 * object, and fills it with the text of <SOURCE_DIRECTORY>/<effect>_paraminfo.txt.
 * The comment is scripted as "paraminfo_comment"; repeated bangs SKIP rnbo~
 * objects that already have one, so nothing is duplicated. Cancel removes only
 * unfinished work from the queue, not comments already created.
 * Uses Max File/Folder/Task/Patcher APIs, not Node's fs or npm packages.
 */

var SOURCE_DIRECTORY = "/REPLACE/WITH/YOUR/RNBO";
var DEFER_MS = 50; // Give Max time to update each subpatcher before the next.
var COMMENT_WIDTH = 460; // Matches a 450-500px wide rnbo~ host footprint.
var COMMENT_LINE_HEIGHT = 15; // Approximate wrapped-text line height in px.
var COMMENT_GAP = 10; // Vertical gap between the out~ bottom and the comment.

inlets = 1;
outlets = 1;

var scriptContext = this;
var queue = null;
var scheduledTask = null;

function bang() { addComments(); }

function addComments() {
    if (queue) {
        error("Paraminfo comments: already running; send cancel first.\n");
        return;
    }
    try {
        const parent = scriptContext.patcher;
        if (!parent) throw new Error("No patcher context.");
        const directory = String(SOURCE_DIRECTORY).replace(/\/+$/, "");
        if (!directory || directory.indexOf("/REPLACE/") === 0) {
            throw new Error("Set SOURCE_DIRECTORY at the top of this script first.");
        }
        // Collect every valid rnbo~ in this patcher. The effect name comes from
        // @annotation_name; scripted names like rnbo_test_<name> are the fallback
        // so manually named rnbo~ objects work too.
        const targets = [];
        for (let obj = parent.firstobject; obj; obj = obj.nextobject) {
            if (!obj || !obj.valid || obj.maxclass !== "rnbo~") continue;
            let effectName = null;
            try { effectName = obj.getattr("annotation_name"); } catch (ignored) {}
            if (typeof effectName !== "string" || !effectName.length) {
                effectName = fallbackNameFromVarname(obj.varname);
            }
            if (!effectName) {
                post("Paraminfo comments: unnamed rnbo~ at " + describeRect(obj) +
                    " has no annotation_name or matching varname; skipped.\n");
                outlet(0, "skipped", "<unnamed rnbo~>", "no effect name");
                continue;
            }
            const sub = obj.subpatcher();
            if (!sub) {
                reportProblem(effectName, "rnbo~ did not expose its subpatcher.");
                continue;
            }
            targets.push({ effectName: effectName, subpatcher: sub });
        }
        if (!targets.length) {
            post("Paraminfo comments: no rnbo~ objects found in this patch.\n");
            outlet(0, "done", 0, 0, 0);
            return;
        }
        queue = { directory: directory, targets: targets, index: 0,
            added: 0, skipped: 0, failed: 0 };
        post("Paraminfo comments: found " + targets.length + " rnbo~ objects.\n");
        schedule(nextTarget);
    } catch (e) { reportProblem("patcher", e); queue = null; }
}

function nextTarget() {
    if (!queue) return;
    if (queue.index >= queue.targets.length) {
        post("Paraminfo comments: done — " + queue.added + " added, " +
            queue.skipped + " skipped, " + queue.failed +
            " failed. Existing comments were left untouched.\n");
        outlet(0, "done", queue.added, queue.skipped, queue.failed);
        queue = null;
        scheduledTask = null;
        return;
    }
    let target = queue.targets[queue.index++];
    try {
        // A run may have scripted the name already; one comment per rnbo~.
        if (findNamed(target.subpatcher, "paraminfo_comment")) {
            queue.skipped++;
            post("Paraminfo comments: skip existing comment in " +
                target.effectName + ".\n");
            outlet(0, "skipped", target.effectName, "comment exists");
            schedule(nextTarget);
            return;
        }
        const out = findOutOne(target.subpatcher);
        if (!out) {
            queue.failed++;
            reportProblem(target.effectName, "no `out~ 1` object in the rnbo~ subpatcher.");
            schedule(nextTarget);
            return;
        }
        const path = queue.directory + "/" + target.effectName + "_paraminfo.txt";
        const text = readSource(path);
        // Top-left corner directly below the `out~ 1` object.
        const rect = out.rect;
        if (!rect) throw new Error("out~ 1 reported no rect.");
        const x = rect[0];
        const y = rect[3] + COMMENT_GAP;
        const comment = target.subpatcher.newdefault(x, y, "comment");
        if (!comment || !comment.valid) throw new Error("Could not create comment.");
        comment.varname = "paraminfo_comment";
        comment.message("set", text);
        const rect2 = [x, y, x + COMMENT_WIDTH, y + estimateHeight(text)];
        comment.rect = rect2;
        post("Paraminfo comments: added comment under out~ 1 of " +
            target.effectName + " at [" + x + ", " + y + "].\n");
        outlet(0, "added", target.effectName, x, y);
        queue.added++;
        schedule(nextTarget);
    } catch (e) {
        queue.failed++;
        reportProblem(target.effectName, e);
        schedule(nextTarget);
    }
}

function cancel() {
    if (scheduledTask) scheduledTask.cancel();
    scheduledTask = null;
    if (!queue) return;
    const remaining = queue.targets.length - queue.index;
    post("Paraminfo comments: canceled; " + queue.added +
        " comments created, remaining targets dropped.\n");
    outlet(0, "canceled", queue.added, remaining);
    queue = null;
}

function schedule(fn) {
    scheduledTask = new Task(fn, scriptContext);
    scheduledTask.schedule(DEFER_MS);
}

// Prefer `out~ 1`: the out~ whose first literal argument is 1, i.e. exact
// boxtext "out~ 1" or scripted audio_out_1 from generate_test_patchers.js.
// Generic `out~` created with the outlet number embedded also matches;
// any leftover out~ 1-less box falls back to the leftmost out~.
function findOutOne(sub) {
    const candidates = [];
    for (let obj = sub.firstobject; obj; obj = obj.nextobject) {
        if (!obj || !obj.valid) continue;
        if (obj.maxclass !== "out~") continue;
        const text = String(obj.boxtext || "");
        if (/^out~\s+1(\s|$)/.test(text)) return obj;
        if (obj.varname === "audio_out_1") return obj;
        candidates.push(obj);
    }
    if (!candidates.length) return null;
    // Fall back to the leftmost out~ (lowest x, matching `out~ 1`'s spot),
    // preferring unsuffixed out~ boxes over out~ 2/3 which sit further right.
    const single = candidates.filter(obj => String(obj.boxtext || "") === "out~");
    const pool = single.length ? single : candidates;
    let best = pool[0];
    for (let i = 1; i < pool.length; i++) {
        if (pool[i].rect && pool[i].rect[0] < best.rect[0]) best = pool[i];
    }
    return best;
}

function fallbackNameFromVarname(varname) {
    const match = /^rnbo_test_(.+)$/.exec(String(varname || ""));
    return match ? match[1] : null;
}

function describeRect(obj) {
    try {
        const r = obj.rect;
        return "[" + r[0] + ", " + r[1] + "]";
    } catch (ignored) { return "[?]"; }
}

function findNamed(sub, name) {
    for (let obj = sub.firstobject; obj; obj = obj.nextobject) {
        if (obj.varname === name) return obj;
    }
    return null;
}

// Crude-but-safe wrap estimate for a fixed-width comment: count explicit
// lines, then Math.ceil(segment-length / chars-per-line) for each segment.
function estimateHeight(text) {
    const charsPerLine = Math.max(24, Math.floor(COMMENT_WIDTH / 6.4));
    let lines = 0;
    const paragraphs = String(text).split("\n");
    for (let i = 0; i < paragraphs.length; i++) {
        const segment = paragraphs[i];
        lines += Math.max(1, Math.ceil(segment.length / charsPerLine));
    }
    return lines * COMMENT_LINE_HEIGHT + 10;
}

function reportProblem(effectName, e) {
    const message = String(e && e.message || e);
    error("Paraminfo comments: " + effectName + ": " + message + "\n");
    outlet(0, "failed", effectName, message);
}

function readSource(path) {
    const file = new File(path, "read");
    if (!file.isopen) throw new Error("Cannot read " + path);
    try {
        // Decode UTF-8 as bytes, preserving Unicode license notices and long lines.
        const chunks = [];
        while (file.position < file.eof) {
            const before = file.position;
            chunks.push(...file.readbytes(Math.min(16384, file.eof - file.position)));
            if (file.position <= before) throw new Error("Read stalled: " + path);
        }
        const source = decodeUTF8(chunks);
        if (!source.trim()) throw new Error("Empty source: " + path);
        return source;
    } finally { file.close(); }
}

// Max v8 versions differ in their browser globals. Decode File.readbytes()
// directly instead of requiring TextDecoder, Buffer, or a Node module.
function decodeUTF8(bytes) {
    const text = [];
    for (let i = 0; i < bytes.length;) {
        const start = i;
        const first = bytes[i++] & 255;
        let value;
        let remaining;
        let minimum;
        if (first < 0x80) {
            value = first; remaining = 0; minimum = 0;
        } else if (first >= 0xC2 && first <= 0xDF) {
            value = first & 0x1F; remaining = 1; minimum = 0x80;
        } else if (first >= 0xE0 && first <= 0xEF) {
            value = first & 0x0F; remaining = 2; minimum = 0x800;
        } else if (first >= 0xF0 && first <= 0xF4) {
            value = first & 7; remaining = 3; minimum = 0x10000;
        } else {
            throw new Error("Invalid UTF-8 at byte " + start);
        }
        if (i + remaining > bytes.length) throw new Error("Truncated UTF-8 at byte " + start);
        for (let j = 0; j < remaining; j++) {
            const next = bytes[i++] & 255;
            if ((next & 0xC0) !== 0x80) throw new Error("Invalid UTF-8 continuation at byte " + (i - 1));
            value = value * 64 + (next & 0x3F);
        }
        if (value < minimum || value > 0x10FFFF || (value >= 0xD800 && value <= 0xDFFF)) {
            throw new Error("Invalid UTF-8 code point at byte " + start);
        }
        if (value <= 0xFFFF) text.push(String.fromCharCode(value));
        else {
            value -= 0x10000;
            text.push(String.fromCharCode(0xD800 + (value >> 10), 0xDC00 + (value & 0x3FF)));
        }
    }
    // Match conventional UTF-8 text reading: discard an optional leading BOM.
    if (text[0] === "\uFEFF") text.shift();
    return text.join("");
}
